package local.blackmamba.vpn;
import org.json.*;import java.util.*;
/** Keep selections across rotated credentials/addresses; never guess ambiguous matches. */
public final class SubscriptionIdentity {
 static String endpoint(JSONObject n){JSONObject o=n.optJSONObject("outbound");if(o==null)return "";String host=o.optString("server");int port=o.optInt("server_port");if(host.isEmpty()){JSONObject x=o.optJSONObject("xray");if(x!=null){JSONObject settings=x.optJSONObject("settings");JSONArray a=settings==null?null:settings.optJSONArray("vnext");if(a==null&&settings!=null)a=settings.optJSONArray("servers");JSONObject first=a==null?null:a.optJSONObject(0);if(first!=null){host=first.optString("address");port=first.optInt("port");}}}return host.isEmpty()?"":host+":"+port;}
 public static JSONObject match(JSONObject old,JSONArray nodes,Set<String> used){JSONObject best=null;int score=0;boolean ambiguous=false;for(int i=0;i<nodes.length();i++){JSONObject n=nodes.optJSONObject(i);if(n==null||used.contains(n.optString("id"))||!n.optString("profile").equals(old.optString("profile")))continue;boolean name=n.optString("name").equals(old.optString("name")),host=!endpoint(old).isEmpty()&&endpoint(n).equals(endpoint(old)),protocol=n.optString("protocol").equals(old.optString("protocol"));int candidate=host&&name?3:host&&protocol?2:name&&protocol?1:0;if(candidate>score){score=candidate;best=n;ambiguous=false;}else if(candidate>0&&candidate==score)ambiguous=true;}return ambiguous?null:best;}
 public static String groupReplacement(JSONObject old,JSONArray nodes){String match="";for(int i=0;i<nodes.length();i++){JSONObject n=nodes.optJSONObject(i);if(!n.optString("profile").equals(old.optString("profile")))continue;JSONArray aliases=n.optJSONArray("legacyIds");boolean found=false;for(int j=0;aliases!=null&&j<aliases.length();j++)if(aliases.optString(j).equals(old.optString("id")))found=true;if(!found)continue;if(old.optString("name").startsWith(n.optString("name")+" · "))return n.optString("id");if(!match.isEmpty())return "";match=n.optString("id");}return match;}
 public static void remapGroupReferences(JSONObject data,JSONArray nodes)throws JSONException{JSONArray old=data.getJSONArray("servers");Map<String,String> map=new HashMap<>();for(int i=0;i<old.length();i++){JSONObject n=old.getJSONObject(i);String replacement=groupReplacement(n,nodes);if(!replacement.isEmpty())map.put(n.getString("id"),replacement);}for(String k:new String[]{"wifi","cellular","fallbackWifi","fallbackCellular"})if(map.containsKey(data.optString(k)))data.put(k,map.get(data.optString(k)));String target=data.optString("defaultTarget");if(target.startsWith("server:")&&map.containsKey(target.substring(7)))data.put("defaultTarget","server:"+map.get(target.substring(7)));JSONArray rules=data.getJSONArray("rules");for(int i=0;i<rules.length();i++){JSONObject r=rules.getJSONObject(i);target=r.optString("target");if(target.startsWith("server:")&&map.containsKey(target.substring(7)))r.put("target","server:"+map.get(target.substring(7)));}}
 public static JSONArray retainIds(JSONArray previous,JSONArray incoming)throws JSONException{
  JSONArray next=new JSONArray(incoming.toString());Set<String> used=new HashSet<>();Map<String,String> ids=new HashMap<>();
  for(int i=0;i<previous.length();i++){JSONObject old=previous.getJSONObject(i);for(int j=0;j<incoming.length();j++){JSONObject n=incoming.getJSONObject(j);if(old.optString("profile").equals(n.optString("profile"))&&old.getString("id").equals(n.getString("id"))){used.add(n.getString("id"));ids.put(n.getString("id"),old.getString("id"));break;}}}
  for(int i=0;i<previous.length();i++){JSONObject old=previous.getJSONObject(i);if(ids.containsValue(old.getString("id")))continue;JSONObject candidate=match(old,incoming,used);if(candidate!=null){used.add(candidate.getString("id"));ids.put(candidate.getString("id"),old.getString("id"));}}
  Set<String> finalIds=new HashSet<>();for(int i=0;i<next.length();i++){JSONObject n=next.getJSONObject(i);String id=ids.getOrDefault(n.getString("id"),n.getString("id"));if(!finalIds.add(id))throw new JSONException(L10n.s(R.string.msg_d721e92378));n.put("id",id);}return next;
 }
}
